function nextHarvestBatchV107(date,state){
  const d=String(date||new Date().toISOString().slice(0,10));
  const rx=new RegExp('^'+d+'-(\\d+)$');
  let max=0;
  ((state&&state.logs&&state.logs.harvests)||[]).forEach(x=>{
    const m=String(x.batch||'').match(rx);
    if(m) max=Math.max(max,Number(m[1])||0);
  });
  return d+'-'+String(max+1).padStart(2,'0');
}
function syncHarvestBatchV107(input){
  const form=input&&input.form;
  if(!form)return;
  const batch=form.elements['Batch_Name'];
  if(batch)batch.value=nextHarvestBatchV107(input.value,v45s());
}
function saveRec(type){
  const s=v45s(),fd=new FormData(idq('rform')),hiveId=fd.get('hiveId'),recordHive=hive(s,hiveId),today=v2p1bDateInHiveTimezone(s,recordHive),notes=fd.get('Notes')||'';
  if(type==='feeding'){
    s.logs.feedings.push({id:'f'+Date.now(),hiveId,date:fd.get('Date')||today,type:fd.get('Feed_Type'),ratio:fd.get('Syrup_Ratio'),amount:(fd.get('Quantity_Value')||'0')+' '+(fd.get('Quantity_Unit')||''),notes,nextFeeding:fd.get('Next_Feeding')||''});
  }else if(type==='treatment'){
    const treatmentId='t'+Date.now();
    const followUp=fd.get('Follow_up')||'';
    let treatmentStatus=String(fd.get('Treatment_Status')||'Active').trim()||'Active';
    const endDate=fd.get('End_Date')||'';
    if(endDate&&['active','planned','活跃','进行中','计划中'].includes(String(treatmentStatus||'').trim().toLowerCase()))treatmentStatus='Completed';
    if((treatmentStatus==='Completed'||treatmentStatus==='Stopped')&&!endDate)return toast('End date is required for a completed or stopped Treatment');
    s.logs.treatments.push({
      id:treatmentId,hiveId,date:fd.get('Start_Date')||today,problem:fd.get('Problem'),type:fd.get('Treatment'),product:fd.get('Product'),
      activeIngredient:fd.get('Active_Ingredient')||'',applicationMethod:fd.get('Application_Method')||'',concentration:fd.get('Concentration')||'',
      dose:fd.get('Dose'),endDate,followUp,withdrawal:fd.get('Withdrawal')||'',honeySupersStatus:String(fd.get('Honey_Supers_Status')||'').trim()==='Not recorded'?'':(fd.get('Honey_Supers_Status')||''),
      lotNumber:fd.get('Lot_Number')||'',status:treatmentStatus,notes,updatedAt:new Date().toISOString()
    });
    // V2P2D5 — Treatment follow-up is a durable workflow Action, not a
    // generated recommendation. Keep one Action per Treatment and keep its due
    // date synchronized when the Treatment record is edited later.
    s.actions=Array.isArray(s.actions)?s.actions:[];
    const existingFollow=s.actions.find(a=>a&&String(a.hiveId)===String(hiveId)&&a.type==='Treatment'&&String(a.sourceId||'')===String(treatmentId)&&(String(a.source||'')==='treatment-follow-up'||String(a.title||'')==='Treatment follow-up'));
    if(followUp){
      if(existingFollow){
        existingFollow.title='Treatment follow-up';existingFollow.priority='Medium';existingFollow.due=followUp;existingFollow.dueDate=followUp;existingFollow.date=followUp;existingFollow.status='Pending';existingFollow.source='treatment-follow-up';existingFollow.updatedAt=new Date().toISOString();
      }else{
        s.actions.push({id:'a'+Date.now(),type:'Treatment',hiveId,title:'Treatment follow-up',priority:'Medium',due:followUp,dueDate:followUp,date:followUp,status:'Pending',source:'treatment-follow-up',sourceId:treatmentId,createdAt:new Date().toISOString()});
      }
    }else if(existingFollow){
      s.actions=s.actions.filter(a=>a!==existingFollow);
    }
  }else{
    const weight=Number(fd.get('Honey_Weight')||0);
    const weightUnit=fd.get('Honey_Weight_Unit')||'lb';
    const harvestDate=fd.get('Date')||today;
    let harvestBatch=String(fd.get('Batch_Name')||'').trim();
    const autoBatchPattern=new RegExp('^'+harvestDate+'-\\d+$');
    if(!harvestBatch || (autoBatchPattern.test(harvestBatch) && s.logs.harvests.some(x=>String(x.batch||'')===harvestBatch))){
      harvestBatch=nextHarvestBatchV107(harvestDate,s);
    }
    s.logs.harvests.push({
      id:'hv'+Date.now(),
      hiveId,
      date:harvestDate,
      frames:Number(fd.get('Frames_Harvested')||0),
      weightLb:weightUnit==='kg'?Number((weight*2.20462).toFixed(2)):weight,
      weight,
      weightUnit,
      moisture:Number(fd.get('Moisture')||0),
      batch:harvestBatch,
      notes
    });
  }
  save(s);toast('Record saved');go(type==='harvest'?'honey':'actions');
}

