function safeBackV51(fallback='home'){
  const target=String(fallback||'home').replace(/^#/,'');
  try{
    if(typeof go==='function'){
      go(target);
    }else{
      location.hash=target;
    }
  }catch(err){
    console.error('HiveDash back navigation failed',err);
    location.hash=target;
  }
}
