/* ==========================================================
   V199 — TIMELINE BLANK PAGE FIX
   BASE: V198 FULL

   Root cause:
   The current Timeline renderer still referenced:
   - V49_TIMELINE_LIMIT
   - V49_TIMELINE_CACHE
   - V49_TIMELINE_FILTER
   - V49_TIMELINE_FILTER_ROUTE
   - v49TimelineRows()

   but those declarations / row-builder had been lost from the
   current v45.js. The resulting ReferenceError stopped render()
   before chrome('timeline'), producing an empty Timeline screen.

   Scope:
   Restore only Timeline runtime state + row aggregation.
   V197 Hive Actions and V198 Feeding/Treatment remain untouched.
   ========================================================== */
(function(){
  if(window.__V199_TIMELINE_RUNTIME_RESTORE__) return;
  window.__V199_TIMELINE_RUNTIME_RESTORE__=true;

  /* Use window-backed state so the existing Timeline functions can
     resolve these identifiers without changing their UI or routes. */
  if(typeof window.V49_TIMELINE_LIMIT==='undefined') window.V49_TIMELINE_LIMIT=10;
  if(!Array.isArray(window.V49_TIMELINE_CACHE)) window.V49_TIMELINE_CACHE=[];
  if(typeof window.V49_TIMELINE_FILTER!=='string') window.V49_TIMELINE_FILTER='All';
  if(typeof window.V49_TIMELINE_FILTER_ROUTE!=='string') window.V49_TIMELINE_FILTER_ROUTE='';

  /* Expose legacy identifier names through var bindings expected by
     the existing current Timeline renderer. */
  try{
    if(typeof V49_TIMELINE_LIMIT==='undefined') V49_TIMELINE_LIMIT=window.V49_TIMELINE_LIMIT;
  }catch(_){ window.V49_TIMELINE_LIMIT=10; }
  try{
    if(typeof V49_TIMELINE_CACHE==='undefined') V49_TIMELINE_CACHE=window.V49_TIMELINE_CACHE;
  }catch(_){ window.V49_TIMELINE_CACHE=[]; }
  try{
    if(typeof V49_TIMELINE_FILTER==='undefined') V49_TIMELINE_FILTER=window.V49_TIMELINE_FILTER;
  }catch(_){ window.V49_TIMELINE_FILTER='All'; }
  try{
    if(typeof V49_TIMELINE_FILTER_ROUTE==='undefined') V49_TIMELINE_FILTER_ROUTE=window.V49_TIMELINE_FILTER_ROUTE;
  }catch(_){ window.V49_TIMELINE_FILTER_ROUTE=''; }

  window.v49TimelineRows=function(hiveId=''){
    const s=v45s();
    const rows=[];

    const add=(type,x,detail,img='')=>{
      if(!x) return;
      if(hiveId && x.hiveId!==hiveId) return;
      rows.push({
        key:type+':'+String(x.id||Date.now()),
        type,
        hiveId:x.hiveId,
        date:x.date||'',
        detail:detail||'',
        img:img||'',
        /* V224B28: ordering metadata only; UI/data semantics unchanged. */
        savedAt:x.savedAt||'',
        sourceId:String(x.id||'')
      });
    };

    const inspections=Array.isArray(s.logs?.inspections)?s.logs.inspections:[];
    const feedings=Array.isArray(s.logs?.feedings)?s.logs.feedings:[];
    const treatments=Array.isArray(s.logs?.treatments)?s.logs.treatments:[];
    const harvests=Array.isArray(s.logs?.harvests)?s.logs.harvests:[];

    inspections.forEach(x=>
      add('Inspection',x,x.notes||'Inspection saved',V45?.inspection||'')
    );

    feedings.forEach(x=>
      add('Feeding',x,[x.type,x.ratio,x.amount].filter(Boolean).join(' · '))
    );

    treatments.forEach(x=>
      add('Treatment',x,[x.type,x.product,x.dose].filter(Boolean).join(' · '))
    );

    harvests.forEach(x=>
      add(
        'Harvest',
        x,
        [
          typeof formatWeight==='function'
            ? formatWeight(x.weightLb||0,s)
            : String(x.weightLb||0),
          x.moisture ? x.moisture+'% moisture' : ''
        ].filter(Boolean).join(' · '),
        V45?.harvest||''
      )
    );

    (s.hives||[]).forEach(h=>{
      const photos=typeof hivePhotos==='function'
        ? hivePhotos(h)
        : (Array.isArray(h?.photos)?h.photos:[]);

      photos.forEach(p=>{
        if(hiveId && h.id!==hiveId) return;
        rows.push({
          key:'Photo:'+String(p.id||Date.now()),
          type:'Photo',
          hiveId:h.id,
          date:p.date||h.lastInspection||'',
          detail:'Hive photo',
          img:p.data||''
        });
      });
    });

    return rows.sort((a,b)=>{
      const byDate=String(b.date||'').localeCompare(String(a.date||''));
      if(byDate) return byDate;

      /* V224B28 — Inspection Timeline same-day ordering only.
         Save Inspection already stores the current d.notes correctly.
         The stale-looking Timeline was caused by all same-day rows tying on
         YYYY-MM-DD, leaving older Aug 28 rows ahead of the newly saved row.
         For Inspection-vs-Inspection ties, newest savedAt/id wins.
         Other event types keep their existing same-day order. */
      if(a.type==='Inspection' && b.type==='Inspection'){
        const bySaved=String(b.savedAt||'').localeCompare(String(a.savedAt||''));
        if(bySaved) return bySaved;

        const idNum=v=>{
          const m=String(v.sourceId||'').match(/(\d{10,})/);
          return m?Number(m[1]):0;
        };
        return idNum(b)-idNum(a);
      }
      return 0;
    });
  };

  /* The existing timelinePage() calls the identifier directly.
     Create the global identifier without replacing timelinePage(). */
  try{
    v49TimelineRows=window.v49TimelineRows;
  }catch(_){}

  /* If the browser arrived directly on #timeline/... while old code
     had already failed once, rerender only that current route. */
  const root=String(location.hash||'').replace(/^#/,'').split('/')[0];
  if(root==='timeline'){
    setTimeout(()=>{
      try{
        if(typeof render==='function') render();
      }catch(err){
        console.error('V199 Timeline rerender failed',err);
      }
    },0);
  }
})();

/* ==========================================================
   V200 — INSPECTION QUICK SELECT CONTROLS
   BASE: V199 FULL

   Scope ONLY:
   Replace Inspection enum-field browser prompt() interactions with
   a touch-friendly quick-select sheet.

   No field names, draft keys, save logic, page structure, routes,
   Header, Bottom Nav, Photos, Voice Notes, Timeline or Hive Actions
   are changed.
   ========================================================== */
(function(){
  if(window.__V200_INSPECTION_QUICK_SELECT__) return;
  window.__V200_INSPECTION_QUICK_SELECT__=true;

  const ENUMS = {
    queenStatus: {
      label:'Queen Status',
      options:['Seen','Not Seen','Unsure']
    },
    brood: {
      label:'Brood Pattern',
      options:['Excellent','Good','Fair','Poor']
    },
    honey: {
      label:'Honey Stores',
      options:['High','Medium','Low']
    },
    pollen: {
      label:'Pollen Stores',
      options:['High','Medium','Low']
    },
    queenCells: {
      label:'Queen Cells',
      options:['None','Present']
    }
  };

  function closeSheet(){
    document.querySelector('.v200-qs-overlay')?.remove();
  }

  function openSheet(key){
    const cfg=ENUMS[key];
    if(!cfg) return false;

    const draft=window.V49_INSPECTION_DRAFT || {};
    const current=String(draft[key] ?? '');

    closeSheet();
    const overlay=document.createElement('div');
    overlay.className='v200-qs-overlay';
    overlay.innerHTML=`
      <section class="v200-qs-sheet" role="dialog" aria-modal="true" aria-label="${cfg.label}">
        <div class="v200-qs-head">
          <b>${cfg.label}</b>
          <button type="button" class="v200-qs-close" aria-label="Close">×</button>
        </div>
        <div class="v200-qs-options">
          ${cfg.options.map(v=>`
            <button type="button"
                    class="v200-qs-option ${current===v?'is-selected':''}"
                    data-value="${v}">
              <span>${v}</span>
              <span class="v200-qs-check">${current===v?'✓':''}</span>
            </button>
          `).join('')}
        </div>
      </section>`;

    document.body.appendChild(overlay);
    overlay.querySelector('.v200-qs-close').onclick=closeSheet;
    overlay.addEventListener('click',e=>{ if(e.target===overlay) closeSheet(); });

    overlay.querySelectorAll('.v200-qs-option').forEach(btn=>{
      btn.onclick=()=>{
        const value=btn.dataset.value;
        if(!window.V49_INSPECTION_DRAFT) window.V49_INSPECTION_DRAFT={};
        window.V49_INSPECTION_DRAFT[key]=value;
        closeSheet();

        /* Reuse current Inspection renderer/save draft model.
           This does not persist until the existing Save action is used. */
        try{
          if(typeof render==='function') render();
        }catch(err){
          console.error('V200 Inspection quick select render failed',err);
        }
      };
    });
    return true;
  }

  /* Capture only clicks on the five existing Inspection enum rows.
     We deliberately do not modify sliders, Photos, Voice Notes, Save,
     or any row outside #inspection/... */
  document.addEventListener('click',function(e){
    const root=String(location.hash||'').replace(/^#/,'').split('/')[0];
    if(root!=='inspection') return;

    const row=e.target.closest('[data-field], .row, .fieldrow, .inspect-row, .v49-row');
    if(!row) return;

    const text=(row.textContent||'').replace(/\s+/g,' ').trim();
    let key='';
    if(/^Queen Status\b/i.test(text)) key='queenStatus';
    else if(/^Brood Pattern\b/i.test(text)) key='brood';
    else if(/^Honey Stores\b/i.test(text)) key='honey';
    else if(/^Pollen Stores\b/i.test(text)) key='pollen';
    else if(/^Queen Cells\b/i.test(text)) key='queenCells';
    if(!key) return;

    e.preventDefault();
    e.stopImmediatePropagation();
    openSheet(key);
  }, true);

  const style=document.createElement('style');
  style.id='v200-inspection-quick-select-style';
  style.textContent=`
    .v200-qs-overlay{
      position:fixed!important; inset:0!important; z-index:13000!important;
      display:flex!important; align-items:flex-end!important; justify-content:center!important;
      background:rgba(47,59,51,.34)!important;
    }
    .v200-qs-sheet{
      width:min(393px,100vw)!important;
      margin:0!important;
      padding:0 16px calc(18px + env(safe-area-inset-bottom,0px))!important;
      border-radius:18px 18px 0 0!important;
      background:#FFFEFB!important;
      box-shadow:0 -10px 30px rgba(47,59,51,.16)!important;
      box-sizing:border-box!important;
    }
    .v200-qs-head{
      display:flex!important; align-items:center!important; justify-content:space-between!important;
      min-height:58px!important; border-bottom:1px solid #E6E3DA!important;
    }
    .v200-qs-head b{
      color:#2F3B33!important; font-size:17px!important; font-weight:800!important;
    }
    .v200-qs-close{
      width:42px!important; height:42px!important; border:0!important; background:transparent!important;
      color:#5E7350!important; font-size:22px!important; cursor:pointer!important;
    }
    .v200-qs-options{
      display:grid!important; gap:10px!important; padding-top:14px!important;
    }
    .v200-qs-option{
      display:flex!important; align-items:center!important; justify-content:space-between!important;
      width:100%!important; min-height:54px!important; padding:0 16px!important;
      border:1px solid #DDD8CF!important; border-radius:12px!important;
      background:#fff!important; color:#2F3B33!important;
      font:inherit!important; font-size:14px!important; font-weight:700!important;
      text-align:left!important; cursor:pointer!important;
    }
    .v200-qs-option.is-selected{
      border-color:#5E7350!important; background:#F2F5EF!important; color:#36512B!important;
    }
    .v200-qs-check{
      width:24px!important; color:#5E7350!important; font-size:17px!important; text-align:right!important;
    }
  `;
  document.head.appendChild(style);
})();

