/* ==========================================================
   V204 — NEXT INSPECTION REMINDER SYNC FIX
   BASE: V203 FULL

   Scope:
   Complete the existing Next Inspection data chain without changing
   V203 date-picker UI, Inspection structure, Header/Bottom Nav,
   Timeline, Hive Actions, Feeding or Treatment.

   Canonical source:
     current hive.nextInspection

   Synchronization:
     Inspection draft -> existing Save Inspection -> hive.nextInspection
     Actions/reminders derive from hive.nextInspection
     Clear removes the canonical future date.
   ========================================================== */
(function(){
  if(window.__V204_NEXT_INSPECTION_REMINDER_SYNC__) return;
  window.__V204_NEXT_INSPECTION_REMINDER_SYNC__=true;

  function v204State(){
    try{
      if(typeof getState==='function') return getState();
      if(typeof load==='function') return load();
      if(typeof state!=='undefined') return state;
      if(typeof s!=='undefined') return s;
    }catch(_){}
    return null;
  }

  function v204HiveId(){
    return V49_INSPECTION_DRAFT?.hiveId || String(location.hash||'').split('/')[1] || '';
  }

  function v204FindHive(st,hiveId){
    if(!st || !hiveId) return null;
    const pools=[
      st.hives,
      st.data?.hives,
      st.apiary?.hives
    ];
    for(const pool of pools){
      if(Array.isArray(pool)){
        const h=pool.find(x=>String(x?.id)===String(hiveId));
        if(h) return h;
      }
    }
    return null;
  }

  function v204PersistState(st){
    try{
      if(typeof saveState==='function'){ saveState(st); return true; }
      if(typeof save==='function'){ save(st); return true; }
      if(typeof setState==='function'){ setState(st); return true; }
    }catch(e){
      console.error('V204 state persist failed',e);
    }
    return false;
  }

  function v204SyncCanonicalDate(){
    const st=v204State();
    const hiveId=v204HiveId();
    const hive=v204FindHive(st,hiveId);
    if(!hive) return false;

    const next=String(V49_INSPECTION_DRAFT?.nextInspection||'').trim();
    hive.nextInspection=next;

    /* Keep one canonical field on the hive. Do not create duplicate
       persisted Action/Notification records here. */
    v204PersistState(st);
    return true;
  }

  /* Hook the existing Save button at the DOM boundary, before the current
     Save handler consumes/clears the Inspection draft. This preserves the
     current save function and all of its existing record logic. */
  document.addEventListener('click',function(e){
    const root=String(location.hash||'').replace(/^#/,'').split('/')[0];
    if(root!=='inspection') return;

    const el=e.target.closest('button,[role="button"],a');
    if(!el) return;
    const txt=(el.textContent||'').replace(/\s+/g,' ').trim().toLowerCase();

    if(txt==='save' || txt==='save inspection'){
      v204SyncCanonicalDate();
    }
  },true);

  /* Public read helper for existing/next UI renderers. It derives reminder
     status from the hive field instead of maintaining a second copy. */
  window.V204_NEXT_INSPECTION = {
    get(hiveId){
      const st=v204State();
      const hive=v204FindHive(st,hiveId);
      return String(hive?.nextInspection||'').trim();
    },
    status(hiveId){
      const value=this.get(hiveId);
      if(!value) return {date:'',days:null,due:false,upcoming:false};
      const hive=v204FindHive(st,hiveId);
      const target=v2p2d7DayNumber(value),today=v2p2d7DayNumber(v2p2d7TodayForHive(st,hive));
      const days=(target===null||today===null)?null:(target-today);
      return {date:value,days,due:days!==null&&days<=0,upcoming:days!==null&&days>=0&&days<=3};
    }
  };

  /* When V203 Clear is used, mirror the cleared draft into the canonical
     hive immediately. We do not alter V203's picker or its handlers. */
  document.addEventListener('click',function(e){
    const btn=e.target.closest('.v203-clear');
    if(!btn) return;
    setTimeout(v204SyncCanonicalDate,0);
  },true);
})();

/* ==========================================================
   V205 — NEXT INSPECTION ACTIONS DISPLAY FIX
   BASE: V204 FULL

   Scope ONLY:
   Existing Actions page reads hive.nextInspection and displays a
   derived Inspection task with the real date.

   Rules:
   - No new persisted Action record is created.
   - Existing Action data is not modified.
   - Existing Actions page structure/layout is not redesigned.
   - Clicking the derived row opens that Hive's Inspection page.
   - Duplicate derived rows are prevented.
   ========================================================== */
(function(){
  if(window.__V205_NEXT_INSPECTION_ACTIONS_DISPLAY__) return;
  window.__V205_NEXT_INSPECTION_ACTIONS_DISPLAY__=true;

  function v205State(){
    try{
      if(typeof getState==='function') return getState();
      if(typeof load==='function') return load();
      if(typeof state!=='undefined') return state;
      if(typeof s!=='undefined') return s;
    }catch(_){}
    return null;
  }

  function v205Hives(st){
    if(!st) return [];
    if(Array.isArray(st.hives)) return st.hives;
    if(Array.isArray(st.data?.hives)) return st.data.hives;
    if(Array.isArray(st.apiary?.hives)) return st.apiary.hives;
    return [];
  }

  function v205FmtDate(value){
    if(!value) return '';
    try{
      const d=new Date(value+'T00:00:00');
      return d.toLocaleDateString('en-US',{month:'short',day:'numeric'});
    }catch(_){
      return value;
    }
  }

  function v205RenderDerivedRows(){
    const root=String(location.hash||'').replace(/^#/,'').split('/')[0];
    if(root!=='actions') return;

    const st=v205State();
    const hives=v205Hives(st).filter(h=>String(h?.nextInspection||'').trim());
    if(!hives.length) return;

    /* Find the existing Actions list container without changing page structure.
       We append only small rows that reuse the current card/list visual language. */
    const candidates=[
      ...document.querySelectorAll('.actions-list,.action-list,.actioncards,.actions-card,.panel,.card,.vc')
    ];

    let host=candidates.find(el=>{
      const t=String(el.textContent||'');
      return /Pending/i.test(t) && (/Completed/i.test(t) || /All/i.test(t));
    });

    if(!host){
      host=[...document.querySelectorAll('main,section,div')].find(el=>{
        const t=String(el.textContent||'');
        return /Varroa follow-up|Confirm queen status|Review food stores/i.test(t);
      });
    }
    if(!host) return;

    /* Prevent duplicate derived display after rerender. */
    host.querySelectorAll('.v205-next-inspection-action').forEach(el=>el.remove());

    const existingText=String(host.textContent||'').toLowerCase();

    const rows=hives.map(h=>{
      const hiveId=String(h.id||'');
      const hiveName=String(h.name||'Hive');
      const date=String(h.nextInspection||'').trim();
      const dateLabel=v205FmtDate(date);

      /* Avoid showing the same date twice if the existing page already has
         an explicit Inspection row for this hive/date. */
      const normalizedName=hiveName.toLowerCase();
      const normalizedDate=dateLabel.toLowerCase();
      if(existingText.includes(normalizedName) &&
         existingText.includes('inspection') &&
         existingText.includes(normalizedDate)){
        return '';
      }

      return `
        <button type="button"
                class="v205-next-inspection-action"
                onclick="go('inspection/${hiveId}')"
                aria-label="${hiveName} inspection ${dateLabel}">
          <span class="v205-next-left">
            <b>${hiveName}</b>
            <em>Medium</em>
          </span>
          <span class="v205-next-right">
            <b>Inspection</b>
            <em>${dateLabel}</em>
          </span>
        </button>
      `;
    }).filter(Boolean).join('');

    if(!rows) return;

    const wrap=document.createElement('div');
    wrap.className='v205-next-inspection-wrap';
    wrap.innerHTML=rows;

    /* Insert after the Pending/Completed/All controls when possible,
       otherwise before the first existing action row. */
    const tabs=[...host.querySelectorAll('button')].find(b=>/Pending/i.test(b.textContent||''));
    if(tabs){
      const tabBlock=tabs.parentElement;
      if(tabBlock?.nextSibling){
        tabBlock.parentElement.insertBefore(wrap,tabBlock.nextSibling);
      }else{
        tabBlock?.parentElement?.appendChild(wrap);
      }
    }else{
      host.prepend(wrap);
    }
  }

  /* Re-run after current Actions page render without replacing its renderer. */
  const obs=new MutationObserver(()=>{
    const root=String(location.hash||'').replace(/^#/,'').split('/')[0];
    if(root==='actions'){
      clearTimeout(window.__v205ActionsTimer);
      window.__v205ActionsTimer=setTimeout(v205RenderDerivedRows,30);
    }
  });
  obs.observe(document.documentElement,{childList:true,subtree:true});

  window.addEventListener('hashchange',()=>setTimeout(v205RenderDerivedRows,50));
  setTimeout(v205RenderDerivedRows,80);

  const style=document.createElement('style');
  style.id='v205-next-inspection-actions-style';
  style.textContent=`
    .v205-next-inspection-wrap{
      display:grid!important;
      gap:4px!important;
      margin:4px 0!important;
    }

    .v205-next-inspection-action{
      display:grid!important;
      grid-template-columns:1fr 1fr!important;
      align-items:center!important;
      width:100%!important;
      min-height:54px!important;
      padding:7px 10px!important;
      border:1px solid #E6E3DA!important;
      border-radius:9px!important;
      background:#FFFEFB!important;
      color:#2F3B33!important;
      text-align:left!important;
      font:inherit!important;
      cursor:pointer!important;
      box-sizing:border-box!important;
    }

    .v205-next-left,
    .v205-next-right{
      display:flex!important;
      flex-direction:column!important;
      gap:3px!important;
      min-width:0!important;
    }

    .v205-next-right{
      text-align:right!important;
      align-items:flex-end!important;
    }

    .v205-next-inspection-action b{
      display:block!important;
      color:#1F2B24!important;
      font-size:12px!important;
      line-height:1.2!important;
      font-weight:800!important;
    }

    .v205-next-inspection-action em{
      display:block!important;
      color:#C5921A!important;
      font-size:10px!important;
      line-height:1.2!important;
      font-style:normal!important;
      font-weight:600!important;
    }

    .v205-next-right em{
      color:#2F3B33!important;
    }
  `;
  document.head.appendChild(style);
})();

/* ==========================================================
   V206 — NEXT INSPECTION ACTIONS OWNERSHIP FIX
   BASE: V205 FULL

   Root causes fixed:
   1) V204's helper did not reliably use the real state() ownership.
   2) V205 tried to inject DOM after render instead of extending the
      actual Actions data renderer.

   Scope:
   - Persist hive.nextInspection through the real state()/save() path.
   - Extend the actual v53ActionRows() output with a derived Inspection
     row carrying the real date.
   - No persisted Action record is created or modified.
   - Existing Actions page markup/visual structure stays unchanged.
   ========================================================== */
(function(){
  if(window.__V206_NEXT_INSPECTION_ACTIONS_OWNERSHIP__) return;
  window.__V206_NEXT_INSPECTION_ACTIONS_OWNERSHIP__=true;

  /* ---------- 1. Persist canonical date through actual save ownership ---------- */
  const V206_PREVIOUS_SAVE_INSPECTION = window.vSaveInspection;

  window.vSaveInspection=function(id){
    const nextInspection=String(window.V49_INSPECTION_DRAFT?.nextInspection||'').trim();
    const hiveId=String(id||window.V49_INSPECTION_DRAFT?.hiveId||'');

    /* Run the exact existing Inspection save first. */
    const result=V206_PREVIOUS_SAVE_INSPECTION.apply(this,arguments);

    /* Then persist only the canonical hive.nextInspection field via
       the real state() / save() functions from app.js. */
    try{
      const s=state();
      const h=hive(s,hiveId);
      if(h){
        h.nextInspection=nextInspection;
        save(s);
      }
    }catch(err){
      console.error('V206 nextInspection persistence failed',err);
    }

    return result;
  };

  /* V203 Clear should also clear the canonical Hive field immediately. */
  document.addEventListener('click',function(e){
    const clear=e.target.closest?.('.v203-clear');
    if(!clear) return;

    const hiveId=String(window.V49_INSPECTION_DRAFT?.hiveId||'');
    setTimeout(()=>{
      try{
        const s=state();
        const h=hive(s,hiveId);
        if(h){
          h.nextInspection='';
          save(s);
        }
      }catch(err){
        console.error('V206 nextInspection clear failed',err);
      }
    },0);
  },true);

  /* ---------- 2. Extend the real Actions row source ---------- */
  const V206_PREVIOUS_V53_ACTION_ROWS = window.v53ActionRows;

  function v206DateLabel(date){
    if(!date) return '';
    try{
      return new Date(date+'T12:00:00').toLocaleDateString('en-US',{
        month:'short',
        day:'numeric'
      });
    }catch(_){
      return date;
    }
  }

  function v206DerivedInspectionRows(){
    const s=v45s();
    const activeHives=v224ActiveTrackedHives(s),allowedHives=activeHives;

    return allowedHives
      .filter(h=>String(h?.nextInspection||'').trim())
      .map(h=>{
        const date=String(h.nextInspection).trim();
        return {
          id:'derived-next-inspection-'+h.id,
          hiveId:h.id,
          type:'inspection',
          title:'Inspection',
          priority:'Medium',
          status:'Pending',
          due:v206DateLabel(date),
          date,
          __v206Derived:true
        };
      })
      .sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
  }

  window.v53ActionRows=function(mode='Pending'){
    const base=V206_PREVIOUS_V53_ACTION_ROWS.apply(this,arguments);
    const normalized=String(mode||'Pending').toLowerCase();

    if(normalized==='completed') return base;

    const derived=v206DerivedInspectionRows();

    /* Prevent duplicate display if the current renderer/data already
       contains the same derived hive/date inspection task. */
    const seen=new Set(
      (base||[]).map(a=>
        [
          String(a.hiveId||''),
          String(a.type||'').toLowerCase(),
          String(a.date||a.due||'')
        ].join('|')
      )
    );

    const unique=derived.filter(a=>{
      const exact=[
        String(a.hiveId||''),
        'inspection',
        String(a.date||'')
      ].join('|');

      if(seen.has(exact)) return false;

      /* Also avoid another V206-derived row for the same Hive. */
      if((base||[]).some(x=>String(x.id||'')==='derived-next-inspection-'+a.hiveId)){
        return false;
      }
      return true;
    });

    if(normalized==='all') return [...unique,...base];
    return [...unique,...base];
  };

  /* If user is already on Actions after deploying V206, redraw the real list. */
  if(String(location.hash||'').replace(/^#/,'').split('/')[0]==='actions'){
    setTimeout(()=>{
      try{
        if(typeof v53DrawActions==='function') v53DrawActions('Pending');
      }catch(err){
        console.error('V206 Actions redraw failed',err);
      }
    },60);
  }
})();

/* ==========================================================
   V207 — NEXT INSPECTION PERSISTENCE FIX
   BASE: V206 FULL

   Confirmed runtime fact from browser console:
     localStorage['hd_hives'][0].nextInspection === undefined

   Therefore the break is in persistence, not Actions display.

   Scope ONLY:
   - Mirror V49_INSPECTION_DRAFT.nextInspection into the real hd_hives
     localStorage array for the matching Hive ID when Inspection is saved.
   - Clear it from hd_hives when V203 Clear is used.
   - Keep V206 Actions derivation intact.
   - Do not modify existing Inspection record save logic or page structure.
   ========================================================== */
(function(){
  if(window.__V207_NEXT_INSPECTION_PERSISTENCE__) return;
  window.__V207_NEXT_INSPECTION_PERSISTENCE__=true;

  function v207ReadHives(){
    try{
      const raw=localStorage.getItem('hd_hives');
      const arr=raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr : [];
    }catch(err){
      console.error('V207 read hd_hives failed',err);
      return [];
    }
  }

  function v207WriteHives(arr){
    try{
      localStorage.setItem('hd_hives',JSON.stringify(arr));
      return true;
    }catch(err){
      console.error('V207 write hd_hives failed',err);
      return false;
    }
  }

  function v207HiveId(){
    return String(
      window.V49_INSPECTION_DRAFT?.hiveId ||
      String(location.hash||'').split('/')[1] ||
      ''
    );
  }

  function v207PersistNextInspection(value){
    const hiveId=v207HiveId();
    if(!hiveId) return false;

    const hives=v207ReadHives();
    const index=hives.findIndex(h=>String(h?.id||'')===hiveId);
    if(index<0){
      console.error('V207 hive not found in hd_hives:',hiveId);
      return false;
    }

    const next=String(value||'').trim();
    hives[index]={
      ...hives[index],
      nextInspection:next
    };

    const ok=v207WriteHives(hives);
    if(ok){
      /* Also mirror into the current in-memory state when present so the
         existing V206 Actions derivation can see it immediately. */
      try{
        const s=state();
        const h=hive(s,hiveId);
        if(h) h.nextInspection=next;
      }catch(_){}
    }
    return ok;
  }

  /* Own the exact Save button boundary BEFORE existing save handlers clear
     or replace the draft. We do not stop propagation and do not replace save. */
  document.addEventListener('click',function(e){
    const root=String(location.hash||'').replace(/^#/,'').split('/')[0];
    if(root!=='inspection') return;

    const el=e.target.closest?.('button,[role="button"],a');
    if(!el) return;

    const txt=String(el.textContent||'').replace(/\s+/g,' ').trim().toLowerCase();
    if(txt!=='save' && txt!=='save inspection') return;

    const next=String(window.V49_INSPECTION_DRAFT?.nextInspection||'').trim();
    v207PersistNextInspection(next);
  },true);

  /* V203 Clear -> real hd_hives clear. */
  document.addEventListener('click',function(e){
    const clear=e.target.closest?.('.v203-clear');
    if(!clear) return;

    setTimeout(()=>v207PersistNextInspection(''),0);
  },true);

  /* Public diagnostic helper for QA only. */
  window.V207_NEXT_INSPECTION_QA={
    get(hiveId){
      const h=v207ReadHives().find(x=>String(x?.id||'')===String(hiveId||''));
      return h ? h.nextInspection : undefined;
    }
  };
})();

