    const now=new Date().toISOString(),a={id:'combine-action-'+Date.now(),hiveId:d.sourceHiveId,type:TYPE,title:'Combine Hives',status:'Pending',priority:d.priority||'Medium',due:d.dueDate||TODAY(),dueDate:d.dueDate||TODAY(),date:d.dueDate||TODAY(),createdAt:now,startedAt:null,completedAt:null,followUpDate:null,source:'manual',reasonCode:'management',workflowData:{sourceHiveId:d.sourceHiveId,targetHiveId:d.targetHiveId,sourceCondition:d.sourceCondition,targetCapacity:d.targetCapacity,diseaseCheck:d.diseaseCheck,queenPlan:d.queenPlan,reason:d.reason,method:d.method},resultData:null,linkedRecordId:null,linkedActionId:null,parentActionId:null,notes:d.notes||''};
    if(typeof upsert==='function')upsert(s,a);else{s.actions=Array.isArray(s.actions)?s.actions:[];s.actions.push(a)}
