/* ==============================================================
   V2P2C8 — TIMELINE ENGLISH SUMMARY + DETAIL SHEET POSITION FIX
   Scope ONLY:
   1) Canonicalize legacy localized Treatment enum labels in Timeline list summaries.
      Stored Treatment records are not mutated.
   2) Move Timeline event detail modals upward and give them a larger visible area
      across All / Inspection / Feeding / Treatment / Harvest / Varroa / Photos.
      No business logic, persistence, routing, scoring, or record linkage changes.
   ============================================================== */
(function(){
  if(window.__HIVEDASH_V2_P2C8_TIMELINE_POLISH__)return;
  window.__HIVEDASH_V2_P2C8_TIMELINE_POLISH__=true;

  const txt=v=>String(v??'').trim();

  function canonicalTreatmentNameV2P2C8(v){
    const x=txt(v), compact=x.replace(/\s+/g,'');
    if(!x)return 'Treatment';
    if(/草酸/.test(compact)||/oxalic\s*acid/i.test(x)){
      if(/滴|dribble/i.test(compact))return 'Oxalic Acid (Dribble)';
      if(/蒸|熏|气化|vapor/i.test(compact))return 'Oxalic Acid (Vapor)';
      return 'Oxalic Acid';
    }
    if(/甲酸/.test(compact)||/formic\s*acid/i.test(x))return 'Formic Acid';
    if(/阿米特拉/.test(compact)||/\bapivar\b|\bamitraz\b/i.test(x))return 'Apivar';
    if(/[\u3400-\u9fff]/.test(x))return 'Treatment';
    return x;
  }

  function canonicalTreatmentProductV2P2C8(v){
    const x=txt(v),compact=x.replace(/\s+/g,'');
    if(!x)return '';
    if(/草酸.*溶液/.test(compact)||/oxalic\s*acid\s*solution/i.test(x))return 'Oxalic Acid Solution';
    if(/甲酸/.test(compact)&&/[片带垫剂]/.test(compact))return 'Formic Acid';
    if(/阿米特拉/.test(compact)||/\bapivar\b/i.test(x))return 'Apivar';
    return x;
  }

  const prevRowsV2P2C8=window.v49TimelineRows;
  if(typeof prevRowsV2P2C8==='function'){
    window.v49TimelineRows=function(hiveId=''){
      const rows=prevRowsV2P2C8.apply(this,arguments);
      const s=typeof v45s==='function'?v45s():{};
      const treatments=Array.isArray(s?.logs?.treatments)?s.logs.treatments:[];
      const byId=new Map(treatments.map(x=>[String(x?.id||''),x]));

      rows.forEach(row=>{
        if(!row||row.type!=='Treatment')return;
        const tx=byId.get(String(row.sourceId||String(row.key||'').split(':').slice(1).join(':')));
        if(tx){
          row.detail=[
            canonicalTreatmentNameV2P2C8(tx.type),
            canonicalTreatmentProductV2P2C8(tx.product),
            txt(tx.dose)
          ].filter(Boolean).join(' · ');
          return;
        }
        // Fallback for legacy projected rows without a resolvable source record.
        const parts=txt(row.detail).split(' · ');
        if(parts.length)parts[0]=canonicalTreatmentNameV2P2C8(parts[0]);
        row.detail=parts.join(' · ');
      });
      return rows;
    };
    try{v49TimelineRows=window.v49TimelineRows}catch(_){ }
  }

  if(!document.getElementById('v2p2c8-timeline-modal-style')){
    const st=document.createElement('style');
    st.id='v2p2c8-timeline-modal-style';
    st.textContent=`
      #app>.modal.v2p2c8-timeline-detail-modal{
        place-items:start center!important;
        align-items:start!important;
        justify-items:center!important;
        padding-top:max(56px,calc(env(safe-area-inset-top,0px) + 44px))!important;
        padding-bottom:max(12px,env(safe-area-inset-bottom,0px))!important;
        box-sizing:border-box!important;
        overflow:hidden!important;
      }
      #app>.modal.v2p2c8-timeline-detail-modal>.modalpanel{
        width:min(393px,100%)!important;
        max-height:calc(100dvh - max(80px,calc(env(safe-area-inset-top,0px) + 68px)))!important;
        overflow:auto!important;
        overscroll-behavior:contain!important;
        -webkit-overflow-scrolling:touch!important;
        border-radius:16px!important;
        box-shadow:0 14px 40px rgba(47,59,51,.22)!important;
      }
      @media (max-height:720px){
        #app>.modal.v2p2c8-timeline-detail-modal{
          padding-top:max(38px,calc(env(safe-area-inset-top,0px) + 28px))!important;
        }
        #app>.modal.v2p2c8-timeline-detail-modal>.modalpanel{
          max-height:calc(100dvh - 52px)!important;
        }
      }
    `;
    document.head.appendChild(st);
  }

  const prevOpenTimelineV2P2C8=window.openTimelineEventV49;
  if(typeof prevOpenTimelineV2P2C8==='function'){
    window.openTimelineEventV49=function(key){
      const out=prevOpenTimelineV2P2C8.apply(this,arguments);
      const mark=()=>{
        const candidates=[...document.querySelectorAll('#app>.modal')];
        const m=candidates[candidates.length-1];
        if(m)m.classList.add('v2p2c8-timeline-detail-modal');
      };
      mark();
      requestAnimationFrame(mark);
      return out;
    };
    try{openTimelineEventV49=window.openTimelineEventV49}catch(_){ }
  }

  window.__HIVEDASH_V2_P2C8_VERSION__='v2-p2c8-timeline-english-summary-detail-sheet-position';
})();

/* ==============================================================
   V2P2C9 — TIMELINE TREATMENT DETAIL ENGLISH DISPLAY CANONICALIZATION
   Scope ONLY:
   - Canonicalize legacy/localized Treatment detail enum values in the Timeline modal.
   - Do not mutate stored Treatment records.
   - Do not alter Treatment/Varroa persistence, routing, risk, linkage, or modal position.
   ============================================================== */
(function(){
  if(window.__HIVEDASH_V2_P2C9_TIMELINE_TREATMENT_DETAIL_ENGLISH__)return;
  window.__HIVEDASH_V2_P2C9_TIMELINE_TREATMENT_DETAIL_ENGLISH__=true;

  const txt=v=>String(v??'').trim();
  const noHan=v=>/[\u3400-\u9fff]/.test(txt(v));

  function canonProblem(v){
    const x=txt(v);
    if(!x)return 'Not recorded';
    if(/瓦螨|蜂螨/i.test(x))return 'Varroa Mites';
    return noHan(x)?'Not recorded':x;
  }
  function canonTreatment(v){
    const x=txt(v),k=x.toLowerCase(),c=x.replace(/\s+/g,'');
    if(!x)return 'Not recorded';
    if(/草酸/.test(c)||k.includes('oxalic acid')){
      if(/滴|运球/.test(c)||k.includes('dribble'))return 'Oxalic Acid (Dribble)';
      if(/蒸|熏|气化/.test(c)||k.includes('vapor'))return 'Oxalic Acid (Vapor)';
      return 'Oxalic Acid';
    }
    if(/甲酸/.test(c)||k.includes('formic acid'))return 'Formic Acid';
    if(/阿米特拉/.test(c)||k.includes('apivar')||k.includes('amitraz'))return 'Apivar';
    return noHan(x)?'Treatment':x;
  }
  function canonProduct(v){
    const x=txt(v),k=x.toLowerCase(),c=x.replace(/\s+/g,'');
    if(!x)return 'Not recorded';
    if(/草酸.*溶液/.test(c)||k.includes('oxalic acid solution'))return 'Oxalic Acid Solution';
    if(/甲酸/.test(c)||k.includes('formic acid'))return 'Formic Acid';
    if(/阿米特拉/.test(c)||k.includes('apivar'))return 'Apivar';
    return noHan(x)?'Not recorded':x;
  }
  function canonIngredient(v){
    const x=txt(v),k=x.toLowerCase();
    if(!x)return 'Not recorded';
    if(/草酸/.test(x)||k.includes('oxalic acid'))return 'Oxalic Acid';
    if(/甲酸/.test(x)||k.includes('formic acid'))return 'Formic Acid';
    if(/阿米特拉/.test(x)||k.includes('amitraz'))return 'Amitraz';
    return noHan(x)?'Not recorded':x;
  }
  function canonApplication(v){
    const x=txt(v),k=x.toLowerCase(),c=x.replace(/\s+/g,'');
    if(!x)return 'Not recorded';
    if(k.includes('dribble')||/滴注|滴灌|滴落|滴液|运球/.test(c))return 'Dribble';
    if(k.includes('vapor')||/气化|汽化|蒸发|熏蒸/.test(c))return 'Vapor';
    if(k.includes('strip')||/条带/.test(c))return 'Strip';
    if(k.includes('pad')||/垫/.test(c))return 'Pad';
    if(k.includes('spray')||/喷/.test(c))return 'Spray';
    if(k==='other'||/其他/.test(c))return 'Other';
    return noHan(x)?'Not recorded':x;
  }
  function canonStatus(v){
    const x=txt(v),k=x.toLowerCase();
    if(!x)return 'Not recorded';
    if(k==='active'||/活跃|活动|进行中/.test(x))return 'Active';
    if(k==='planned'||/计划/.test(x))return 'Planned';
    if(k==='completed'||/完成|已完成|完工/.test(x))return 'Completed';
    if(k==='stopped'||/停止|已停止/.test(x))return 'Stopped';
    return noHan(x)?'Not recorded':x;
  }
  function canonWithdrawal(v){
    const x=txt(v),k=x.toLowerCase();
    if(!x)return 'Not recorded';
    if(k==='none'||k==='no'||/无|没有/.test(x))return 'None';
    if(k==='not recorded'||/未录制|未记录/.test(x))return 'Not recorded';
    const days=x.match(/(\d+)\s*(?:天|day)/i);if(days)return `${days[1]} days`;
    return noHan(x)?'Not recorded':x;
  }
  function canonSupers(v){
    const x=txt(v),k=x.toLowerCase(),c=x.replace(/\s+/g,'');
    if(!x)return 'Not recorded';
    if(k==='not present'||k==='absent'||/不在|不存在|无|没有/.test(c))return 'Not present';
    if(k==='present'||/存在|在场|现状/.test(c))return 'Present';
    if(k.includes('removed before treatment')||/治疗前.*移除|处理前.*移除/.test(c))return 'Removed before treatment';
    if(k.includes('honey harvest complete')||/蜂蜜.*采收.*完成|采蜜.*完成/.test(c))return 'Honey harvest complete';
    if(k==='not recorded'||/未录制|未记录/.test(c))return 'Not recorded';
    return noHan(x)?'Not recorded':x;
  }

  const canonByLabel={
    'Problem':canonProblem,
    'Treatment':canonTreatment,
    'Product':canonProduct,
    'Active Ingredient':canonIngredient,
    'Application Method':canonApplication,
    'Status':canonStatus,
    'Withdrawal':canonWithdrawal,
    'Honey Supers Status':canonSupers
  };

  function normalizeLatestTreatmentModal(){
    const modals=[...document.querySelectorAll('#app>.modal')];
    const m=modals[modals.length-1];
    if(!m||!m.querySelector('.v2p2c-treatment-detail'))return;
    m.querySelectorAll('.v2p2c-treatment-detail>div').forEach(row=>{
      const label=txt(row.querySelector('span')?.textContent);
      const valueEl=row.querySelector('b');
      const fn=canonByLabel[label];
      if(!valueEl||!fn)return;
      valueEl.textContent=fn(valueEl.textContent);
      valueEl.setAttribute('translate','no');
      valueEl.classList.add('notranslate');
    });
  }

  const prevOpen=window.openTimelineEventV49;
  if(typeof prevOpen==='function'){
    window.openTimelineEventV49=function(key){
      const out=prevOpen.apply(this,arguments);
      normalizeLatestTreatmentModal();
      requestAnimationFrame(normalizeLatestTreatmentModal);
      setTimeout(normalizeLatestTreatmentModal,0);
      return out;
    };
    try{openTimelineEventV49=window.openTimelineEventV49}catch(_){ }
  }

  window.__HIVEDASH_V2_P2C9_VERSION__='v2-p2c9-timeline-treatment-detail-english';
})();


/* ==============================================================
   V2P2C11 — GLOBAL HARVEST WEIGHT UNIT SOURCE FIX
   Root cause:
   - V45 Harvest dashboard used v45s() and therefore saw the current Weight preference.
   - Legacy Harvest History used state() directly and could still see the old kg value.
   Fix:
   - Persist the V2P2C11 weight policy once from v45s().
   - Harvest History reads v45s() so it shares the exact same Weight preference
     as Harvest dashboard, Timeline, detail and record pages.
   - No harvest values are rewritten; weightLb remains the stored base value.
   ============================================================== */
(function v2p2c11GlobalHarvestWeightSource(){
  if(window.__HIVEDASH_V2P2C11__) return;
  window.__HIVEDASH_V2P2C11__=true;

  window.openHarvestHistory=function(year=window.selectedHarvestYear){
    const s=typeof v45s==='function'?v45s():state();
    const y=Number(year||new Date().getFullYear());
    const rows=[...(s.logs?.harvests||[])]
      .filter(x=>Number(String(x.date||'').slice(0,4))===y)
      .sort((a,b)=>String(b.date).localeCompare(String(a.date)));
    modal(`<div class="modalhead"><div class="h2">Harvest History · ${y}</div><button class="iconbtn" onclick="closeModal(this)">✕</button></div><div class="history-list-master">${rows.length?rows.map(x=>`<button class="history-row-master" onclick="document.querySelector('.modal')?.remove();go('hive/${x.hiveId}')"><i>⌁</i><span><b>${esc(hive(s,x.hiveId)?.name||'Hive')}</b><small>${fmtDate(x.date)} · ${formatWeight(x.weightLb||0,s)} · ${x.moisture||'—'}%</small></span><em>›</em></button>`).join(''):'<div class="small muted">No harvest records for this year.</div>'}</div>`);
  };
})();
window.__HIVEDASH_V2P2C11_VERSION__='v2p2c11';


